window.FE_REFERENCE_ENTRIES = [{"id":"nintendo-game-overview","publisher":"任天堂","source_type":"official","title":"战斗、城市与四条主角路线","published":"2026-09","topics":["角色","战斗","探索"],"summary":"四位主角分别展开故事。准备阶段可训练、招募与建立支援，战斗中需管理烈焰技与 HP。","facts":["凯伊、迪托利希、赛奥朵拉和蕾达分别有自己的故事路线。","烈焰技消耗 HP；烈焰槽过满触发 Burst 后，会失去槽中增益并使最大 HP 减半。","城市中可以招募同伴、提升祝福、训练技能和建立支援关系。"],"url":"https://www.nintendo.com/us/store/products/fire-emblem-fortunes-weave-switch-2/"},{"id":"nintendo-developer-1","publisher":"任天堂","source_type":"official","title":"四条故事路线与后半段合流","published":"2026-09-16","topics":["路线","角色"],"summary":"四条主角路线可以切换，后半段各线培养的角色会汇集。伊修玛尔在序章与过去的故事之间行动。","facts":["四条主角路线以不同视角展开，玩家可以在路线之间切换。","后半段，各路线招募和培养的角色会汇集成一支队伍。","伊修玛尔在序章登场，之后回到过去协助四位主角。"],"url":"https://www.nintendo.com/au/news-and-articles/ask-the-developer-vol-23-fire-emblem-fortunes-weave-chapter-1/"},{"id":"nintendo-developer-2","publisher":"任天堂","source_type":"official","title":"资格考试、转职与多路线培养","published":"2026-09-16","topics":["培养","职业","合流"],"summary":"职业选择与技能资格关联。个人成长率可在游戏中查看，同一人物可在不同路线采用不同培养方式。","facts":["一般情况下，达到技能要求并通过资格考试后，角色可以自由选择职业。","角色个人成长率会在游戏中显示，便于玩家决定培养方向。","同一个人在不同路线或多次游玩中可以采用不同培养方式，后续会合并积累的优势。"],"note":"逐项属性合并公式仍在核对。","url":"https://www.nintendo.com/au/news-and-articles/ask-the-developer-vol-23-fire-emblem-fortunes-weave-chapter-2/"},{"id":"gamersky-character-profiles","publisher":"游民星空","source_type":"guide","title":"成长值与技能生效口径","published":"2026-09-17","topics":["角色","成长","招募"],"summary":"人物基础成长与个人技能生效后的成长分开记录，查询时注意当前技能状态。","facts":["穆的技能生效前后成长值需分开看。","不同口径的数值会并列提示，不直接覆盖。"],"note":"部分成长值仍需游戏内核对。","url":"https://www.gamersky.com/handbook/202609/2211429.shtml"},{"id":"gamersky-recruitment","publisher":"游民星空","source_type":"guide","title":"角色加入条件一览","published":"2026-09-17","topics":["招募","路线"],"summary":"按阵营和篇章查询加入方式。不同路线可能要求不同的支援、名声和道具。","facts":["人物可能随剧情加入，也可能需要满足支援、名声或其他条件。","招募前核对当前主角与篇章，避免把其他路线的要求套用过来。"],"note":"部分译名和条件仍在核对。","url":"https://www.gamersky.com/handbook/202609/2211366.shtml"},{"id":"gamersky-leveling","publisher":"游民星空（转引 GameWith）","source_type":"guide","title":"高效练级方法","published":"2026-09-22","topics":["培养","经验"],"summary":"整理迷宫快速战斗、地图遭遇战、旅馆委托等练级方式，以及各自适合的目标。","facts":["迷宫快速战斗可让出击成员一起获得经验；需要名声时可考虑地图遭遇战。","想重点培养的人物可争取完成最后一击；治疗行动也能获得经验。","现有记录中救世祝福的经验增益为 10%，解锁消耗因果碎片 500。"],"url":"https://www.gamersky.com/handbook/202609/2214500.shtml"},{"id":"gamersky-inheritance","publisher":"游民星空（转引 GameWith）","source_type":"guide","title":"路线共享与因果融合","published":"2026-09-23","topics":["合流","职业","路线"],"summary":"归纳跨路线共享的地图、支援、祝福与职业解锁，并提到第三部的技能等级继承。","facts":["现有记录显示地图探索、支援值、部分祝福与职业解锁可跨路线使用。","现有记录显示第三部因果融合可继承角色在第一部培养的技能等级。","名声等级和所持金不在已整理的继承项内。"],"note":"各项继承细节仍需游戏内核对。","url":"https://www.gamersky.com/handbook/202609/2215308.shtml"},{"id":"gamersky-reroll","publisher":"游民星空（转载 NGA 玩家研究）","source_type":"player","title":"凹点与切职实验记录","published":"2026-09-22","topics":["培养","成长"],"summary":"比较不同职业升级后的属性结果。凹点助手根据目标属性判断取舍，不保证刷新出指定结果。","facts":["职业成长加成可能改变一次升级得到的属性组合。","资格考试是否能刷新成长随机数仍有不同记录。"],"note":"目前只提供凹点取舍策略，刷新方法尚未确认。","url":"https://www.gamersky.com/handbook/202609/2214404.shtml"}];
